#!/bin/bash
# Final receipts: fresh git clone of each published repo at its pinned commit.
MODE=$1; OUT=$2; W=$HOME/receiptE_$(date -u +%Y%m%d_%H%M); rm -rf $W; mkdir -p $W; cd $W
if [ "$MODE" = john ]; then export PATH="$HOME/.local/gitonly:$HOME/.elan/bin:/usr/bin:/bin:/usr/sbin:/sbin:$HOME/.local/bin"; PK=$HOME/lean/clifford/.lake/packages; SHA="shasum -a 256"; ulimit -n 10240; bash $HOME/lean/fix-mathlib.sh >/dev/null 2>&1; else export PATH=$HOME/.elan/bin:$PATH; PK=$HOME/barbier/.lake/packages; SHA=sha256sum; fi
echo "RECEIPT $MODE $(date -u) host=$(hostname) arch=$(uname -m)" > $OUT; echo "lean: $(lean --version)" >> $OUT
echo "===== quadnewton pin 48e94cf944b3dfbcca7358360a064e39b6336d98" >> $OUT; git clone -q https://github.com/jpbald93/quadnewton quadnewton && cd quadnewton && git checkout -q 48e94cf944b3dfbcca7358360a064e39b6336d98 && echo "HEAD $(git rev-parse HEAD) status:$(git status --porcelain | wc -l | tr -d " ")" >> $OUT && echo "mathlib $(grep -A6 '"name": "mathlib"' lake-manifest.json | grep '"rev"' | tr -d ' ",')" >> $OUT && find . -name "*.lean" -not -path "./.git/*" -not -path "./.lake/*" -not -path "./tests/*" | LC_ALL=C sort | xargs $SHA >> $OUT && mkdir -p .lake && ln -s $PK .lake/packages && lake build > build.log 2>&1; echo "build rc=$?" >> $OUT; bash gate.sh 2>&1 | tail -1 >> $OUT; bash tests/tamper.sh 2>&1 | tail -1 >> $OUT; cd $W
echo "===== quadmiquel pin 011c9ecd5276b7abaf2b42a8f5ba463196df123d" >> $OUT; git clone -q https://github.com/jpbald93/quadmiquel quadmiquel && cd quadmiquel && git checkout -q 011c9ecd5276b7abaf2b42a8f5ba463196df123d && echo "HEAD $(git rev-parse HEAD) status:$(git status --porcelain | wc -l | tr -d " ")" >> $OUT && echo "mathlib $(grep -A6 '"name": "mathlib"' lake-manifest.json | grep '"rev"' | tr -d ' ",')" >> $OUT && find . -name "*.lean" -not -path "./.git/*" -not -path "./.lake/*" -not -path "./tests/*" | LC_ALL=C sort | xargs $SHA >> $OUT && mkdir -p .lake && ln -s $PK .lake/packages && lake build > build.log 2>&1; echo "build rc=$?" >> $OUT; bash gate.sh 2>&1 | tail -1 >> $OUT; bash tests/tamper.sh 2>&1 | tail -1 >> $OUT; cd $W
echo "DONE $(date -u)" >> $OUT
